pub fn fmt_u32(buf: MutSpan<u8>, value: u32) -> Span<u8> {
    if value == 0 {
        buf[0] = 48
        return buf[0..1]
    }
    var n: u32 = value
    var tmp: [10]u8 = [0; 10]
    var count: usize = 0
    while n > 0 {
        tmp[count] = 48 + ((n % 10) as u8)
        n = n / 10
        count = count + 1
    }
    var i: usize = 0
    while i < count {
        buf[i] = tmp[count - 1 - i]
        i = i + 1
    }
    return buf[0..count]
}

pub fn main(world: World) -> Void raises {
    let a: u32 = 40
    let b: u32 = 2
    let r: u32 = a + b
    var buf: [10]u8 = [0; 10]
    check world.out.write(fmt_u32(buf, r))
    check world.out.write("\n")
}

